export type BundledLesson = Omit<LessonFrontmatter, 'questions'> & {
  relativePath: string
  body: string
  questions: McqQuestion[]
}

export type BundledTopic = TopicFrontmatter & {
  relativePath: string
  body: string
}

export type ContentBundle = {
  topics: BundledTopic[]
  lessons: BundledLesson[]
  questions: McqQuestion[]
}

type ContentPath = {
  domain: string
  topic: string
  filename: string
  relativePath: string
}

export type ParsedContentSourceFile = {
  relativePath: string
  frontmatter: unknown
  body: string
}

questions = lesson.questions.map((question) => {
    const questionResult = validatedMcqSchema.safeParse(question)
    if (!questionResult.success) {
      return invalidContent(
        path.relativePath,
        questionResult.error.issues.map((issue) => issue.message).join('; '),
      )
    }

    return questionResult.data
  })

lessonViews = sqliteTable('lesson_views', {
  id: text('id').primaryKey(),
  userId: text('user_id').notNull(),
  lessonId: text('lesson_id').notNull(),
  viewedAt: integer('viewed_at', { mode: 'timestamp_ms' }).notNull(),
})

questions = sqliteTable('questions', {
  questionId: text('question_id').primaryKey(),
  answerIndex: integer('answer_index').notNull(),
  // content の集計用 metadata。本文・選択肢・解説は保持しない。
  domain: text('domain').notNull().default(''),
  topic: text('topic').notNull().default(''),
  lessonId: text('lesson_id').notNull().default(''),
  // 直近 content sync に含まれる問題だけを active とする。
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(false),
})

srsStates = sqliteTable(
  'srs_states',
  {
    userId: text('user_id').notNull(),
    questionId: text('question_id').notNull(),
    ease: integer('ease').notNull(), // ease factor を 1000 倍した整数（2.5 → 2500）
    intervalDays: integer('interval_days').notNull(),
    dueAt: integer('due_at', { mode: 'timestamp_ms' }).notNull(),
    reps: integer('reps').notNull(),
    lapses: integer('lapses').notNull(),
    version: integer('version').notNull().default(0),
  },
  (t) => ({
    pk: primaryKey({ columns: [t.userId, t.questionId] }),
  }),
)

users = sqliteTable('users', {
  id: text('id').primaryKey(),
  createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
})

analyticsWeeklyDaySchema = z
  .object({
    date: analyticsWeeklyDateSchema,
    weekday: z.number().int().min(1).max(7),
    answerCount: z.number().int().nonnegative(),
  })
  .superRefine(({ date, weekday }, context) => {
    if (isValidCalendarDate(date) && (new Date(`${date}T00:00:00Z`).getUTCDay() || 7) !== weekday) {
      context.addIssue({
        code: 'custom',
        path: ['weekday'],
        message: 'weekday must match the UTC date',
      })
    }
  })

analyticsWeeklyResponseSchema = z
  .object({
    days: z.array(analyticsWeeklyDaySchema).length(7),
  })
  .superRefine(({ days }, context) => {
    const uniqueDates = new Set(days.map(({ date }) => date))
    days.forEach((day, index) => {
      const previous = days[index - 1]
      if (
        previous &&
        Date.parse(`${day.date}T00:00:00Z`) - Date.parse(`${previous.date}T00:00:00Z`) !==
          86_400_000
      ) {
        context.addIssue({
          code: 'custom',
          path: ['days', index, 'date'],
          message: 'days must be consecutive and in ascending order',
        })
      }
    })
    if (uniqueDates.size !== days.length) {
      context.addIssue({
        code: 'custom',
        path: ['days'],
        message: 'days must contain unique dates',
      })
    }
  })

answerRequestSchema = z
  .object({
    questionId: z.string().min(1),
    // choices は最大6（schema/content の .max(6) と整合）。
    selectedIndex: z.number().int().min(0).max(5),
    responseTimeMs: z.number().int().nonnegative().optional(),
  })
  .strict()

answerResponseSchema = z.object({
  isCorrect: z.boolean(),
  // choices は最大6（schema/content の .max(6) と整合）。
  correctIndex: z.number().int().min(0).max(5),
})

domainsResponseSchema = z
  .object({
    domains: z.array(domainSummarySchema).length(4),
  })
  .superRefine(({ domains }, context) => {
    const uniqueDomains = new Set(domains.map(({ domain }) => domain))
    if (uniqueDomains.size !== domains.length) {
      context.addIssue({
        code: 'custom',
        path: ['domains'],
        message: 'domains must contain each domain exactly once',
      })
    }
  })

mistakeItemSchema = z
  .object({
    questionId: z.string().min(1),
    incorrectRate: z.number().min(0).max(100),
    answerCount: z.number().int().min(2),
    incorrectAnswerCount: z.number().int().nonnegative(),
  })
  .superRefine(({ answerCount, incorrectAnswerCount, incorrectRate }, context) => {
    if (incorrectRate !== Math.round((incorrectAnswerCount / answerCount) * 1000) / 10) {
      context.addIssue({
        code: 'custom',
        path: ['incorrectRate'],
        message: 'incorrectRate must match the counts rounded to one decimal place',
      })
    }
    if (incorrectAnswerCount > answerCount) {
      context.addIssue({
        code: 'custom',
        path: ['incorrectAnswerCount'],
        message: 'incorrectAnswerCount must not exceed answerCount',
      })
    }
  })

mistakesResponseSchema = z
  .object({
    items: z.array(mistakeItemSchema).max(10),
  })
  .superRefine(({ items }, context) => {
    items.forEach((item, index) => {
      const previous = items[index - 1]
      if (previous && compareMistakeRank(previous, item) > 0) {
        context.addIssue({
          code: 'custom',
          path: ['items', index],
          message: 'items must follow mistake ranking order',
        })
      }
    })
  })

rateLimitedErrorResponseSchema = z.object({
  error: z.object({
    code: z.literal('RATE_LIMITED'),
    message: z.literal('Too Many Requests'),
  }),
})

rateLimitUnavailableErrorResponseSchema = z.object({
  error: z.object({
    code: z.literal('RATE_LIMIT_UNAVAILABLE'),
    message: z.literal('Rate limit unavailable'),
  }),
})

retentionDistributionSchema = z.object({
  masteredCount: z.number().int().nonnegative(),
  learningCount: z.number().int().nonnegative(),
  dueCount: z.number().int().nonnegative(),
})

reviewQueueResponseSchema = z.object({
  hasMore: z.boolean(),
  items: z
    .array(
      z.object({
        questionId: z.string().min(1),
        // Unix epoch milliseconds（SRS の dueAt と同じ表現）。
        dueAt: z.number().int().nonnegative(),
      }),
    )
    .max(20),
})

DOMAIN_LABELS: Record<DomainKey, { label: string; order: number }> = {
  security: { label: 'セキュリティ', order: 1 },
  frontend: { label: 'フロントエンド', order: 2 },
  backend: { label: 'バックエンド', order: 3 },
  architecture: { label: 'アーキテクチャ', order: 4 },
}

topicFrontmatterSchema = z.object({
  topic: z.string().min(1),
  title: z.string().min(1),
  order: z.number().int().nonnegative(),
})

validatedLessonFrontmatterSchema = lessonFrontmatterSchema.superRefine(
  (lesson, ctx) => {
    const questionIdPattern = new RegExp(`^${lesson.lessonId}-q\\d+$`)

    for (const [i, question] of lesson.questions.entries()) {
      if (!questionIdPattern.test(question.id)) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: `questionId must match pattern ${lesson.lessonId}-q<number>`,
          path: ['questions', i, 'id'],
        })
      }
    }
  },
)

validatedMcqSchema = mcqQuestionSchema.refine(
  (q) => q.answerIndex < q.choices.length,
  {
    message: 'answerIndex must point to an existing choice',
    path: ['answerIndex'],
  },
)

export type SrsInput = {
  ease: number
  intervalDays: number
  reps: number
  lapses: number
}
